import java.util.*;

public class Main {
    static final int MX = 5500;
    static final long INF = 1000000007L;
    static int n, m, k, c, d;
    static int u, v, mx, s = MX - 2, t = MX - 1, mf = 0, tr[] = new int[MX];
    static long ans = 0, dis[] = new long[MX];
    static PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.first));
    static List<SEdge>[] adj = new ArrayList[MX];

    static {
        for (int i = 0; i < MX; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static class SEdge {
        int v, c, ind, cap;

        SEdge(int v, int c, int ind, int cap) {
            this.v = v;
            this.c = c;
            this.ind = ind;
            this.cap = cap;
        }
    }

    static class Pair {
        long first;
        int second;

        Pair(long first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static void add_edge(int u, int v, int c, int cap) {
        int s1 = adj[u].size();
        int s2 = adj[v].size();
        adj[u].add(new SEdge(v, c, s2, cap));
        adj[v].add(new SEdge(u, -c, s1, 0));
    }

    static void dijkstra() {
        Arrays.fill(dis, 0, MX, INF);
        pq.clear();
        dis[s] = 0;
        pq.add(new Pair(0, s));
        while (!pq.isEmpty()) {
            Pair u = pq.poll();
            if (u.first > dis[u.second]) continue;
            for (SEdge ed : adj[u.second]) {
                if (ed.cap > 0 && dis[ed.v] > u.first + ed.c) {
                    tr[ed.v] = ed.ind;
                    dis[ed.v] = u.first + ed.c;
                    pq.add(new Pair(dis[ed.v], ed.v));
                }
            }
        }
    }

    static void trace() {
        int mxFlow = k, v = t;
        while (v != s) {
            int u = adj[v].get(tr[v]).v;
            int ind = adj[v].get(tr[v]).ind;
            mxFlow = Math.min(mxFlow, adj[u].get(ind).cap);
            v = u;
        }
        mf += mxFlow;
        ans += (long) mxFlow * dis[t];
        v = t;
        while (v != s) {
            int u = adj[v].get(tr[v]).v;
            int ind = adj[v].get(tr[v]).ind;
            adj[v].get(tr[v]).cap += mxFlow;
            adj[u].get(ind).cap -= mxFlow;
            v = u;
        }
    }

    static int at(int u, int t) {
        return u + t * n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();
        mx = n + k;

        for (int i = 0; i < k; i++) {
            u = sc.nextInt();
            add_edge(s, at(u, 0), 0, 1);
        }

        for (int i = 0; i <= mx; i++) {
            add_edge(at(1, i), t, c * i, k);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < mx; j++) {
                add_edge(at(i, j), at(i, j + 1), 0, k);
            }
        }

        for (int i = 0; i < m; i++) {
            u = sc.nextInt();
            v = sc.nextInt();
            for (int j = 0; j < k; j++) {
                for (int j2 = 0; j2 < mx; j2++) {
                    add_edge(at(u, j2), at(v, j2 + 1), d * (2 * j + 1), 1);
                    add_edge(at(v, j2), at(u, j2 + 1), d * (2 * j + 1), 1);
                }
            }
        }

        while (mf < k) {
            dijkstra();
            trace();
        }
        System.out.println(ans);
        sc.close();
    }
}
